{
  "test_cases": [
    {
      "id": "TC-041-01",
      "title": "Relocation of location items when a new balise group becomes SOLR",
      "covers": [
        "ETC-041"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in operational mode. A balise group BG_A is currently the SOLR. A location item LI_1 is defined with a distance of 100m relative to BG_A. A new balise group BG_B is detected and becomes the new SOLR. The distance between BG_A and BG_B is known from linking information as 50m (BG_B is 50m ahead of BG_A).",
      "test_inputs": "Balise group BG_A (SOLR), Location Item LI_1 (dist=100m, ref=BG_A), Balise group BG_B (new SOLR), Linking info: dist(BG_A, BG_B)=50m.",
      "assumptions": "The OBU correctly identifies BG_B as the new SOLR upon detection. The linking information provides the exact distance between the former and new SOLR.",
      "steps": [
        {
          "no": 1,
          "action": "Detect balise group BG_B and update SOLR to BG_B.",
          "expected": "The OBU identifies BG_B as the new SOLR."
        },
        {
          "no": 2,
          "action": "Evaluate the location item LI_1 relative to the new SOLR BG_B.",
          "expected": "The distance of LI_1 is recalculated as 100m - 50m = 50m relative to BG_B."
        },
        {
          "no": 3,
          "action": "Verify the internal state of the location item LI_1.",
          "expected": "The location item LI_1 is stored with a distance of 50m and reference balise group BG_B."
        }
      ]
    },
    {
      "id": "TC-041-02",
      "title": "Relocation of location items when evaluating non-SOLR referenced information",
      "covers": [
        "ETC-041"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The OBU is in operational mode. Balise group BG_A is the current SOLR. A location item LI_2 is defined with a distance of 200m relative to a non-SOLR balise group BG_C. The distance between BG_C and BG_A (SOLR) is known from travelled distance as 100m (BG_C is 100m behind BG_A).",
      "test_inputs": "Balise group BG_A (SOLR), Location Item LI_2 (dist=200m, ref=BG_C), Travelled distance info: dist(BG_C, BG_A)=100m.",
      "assumptions": "The OBU evaluates location based information referred to BG_C while BG_A is the SOLR. The travelled distance calculation is accurate.",
      "steps": [
        {
          "no": 1,
          "action": "Trigger evaluation of location based information referred to BG_C.",
          "expected": "The OBU initiates the relocation process for LI_2."
        },
        {
          "no": 2,
          "action": "Calculate the new distance of LI_2 relative to SOLR BG_A.",
          "expected": "The distance is recalculated as 200m - (-100m) = 300m (since BG_C is behind BG_A, the offset is negative, so subtracting a negative adds). Alternatively, if the formula is strictly 'subtract distance between former ref and SOLR', and distance is signed: 200 - (-100) = 300. If distance is magnitude and direction is handled by sign: 200 + 100 = 300."
        },
        {
          "no": 3,
          "action": "Verify the internal state of the location item LI_2.",
          "expected": "The location item LI_2 is stored with a distance of 300m and reference balise group BG_A."
        }
      ]
    },
    {
      "id": "TC-041-03",
      "title": "Relocation with min/max adjustments (Boundary)",
      "covers": [
        "ETC-041"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The OBU is in operational mode. Balise group BG_A is the current SOLR. A location item LI_3 is defined with a distance of 10m relative to BG_A. A new balise group BG_B becomes SOLR. The distance between BG_A and BG_B is 20m (BG_B is 20m ahead). The calculated new distance is 10m - 20m = -10m. According to SUBSET-026 §3.6.4.2.5, if the resulting distance is outside the valid range (e.g., negative or exceeding max), min/max adjustments apply. Assume the minimum valid distance is 0m.",
      "test_inputs": "Balise group BG_A (SOLR), Location Item LI_3 (dist=10m, ref=BG_A), Balise group BG_B (new SOLR), Linking info: dist(BG_A, BG_B)=20m.",
      "assumptions": "The minimum valid distance for a location item is 0m. The OBU applies the min adjustment as per SUBSET-026 §3.6.4.2.5.",
      "steps": [
        {
          "no": 1,
          "action": "Detect balise group BG_B and update SOLR to BG_B.",
          "expected": "The OBU identifies BG_B as the new SOLR."
        },
        {
          "no": 2,
          "action": "Calculate the new distance of LI_3 relative to BG_B.",
          "expected": "The raw calculated distance is 10m - 20m = -10m."
        },
        {
          "no": 3,
          "action": "Apply min/max adjustments to the calculated distance.",
          "expected": "The distance is adjusted to the minimum valid value of 0m."
        },
        {
          "no": 4,
          "action": "Verify the internal state of the location item LI_3.",
          "expected": "The location item LI_3 is stored with a distance of 0m and reference balise group BG_B."
        }
      ]
    },
    {
      "id": "TC-041-04",
      "title": "Relocation using travelled distance when linking information is unavailable",
      "covers": [
        "ETC-041"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "The OBU is in operational mode. Balise group BG_A is the current SOLR. A location item LI_4 is defined with a distance of 50m relative to BG_A. A new balise group BG_B becomes SOLR. Linking information between BG_A and BG_B is unavailable. The OBU has recorded a travelled distance of 30m since passing BG_A.",
      "test_inputs": "Balise group BG_A (SOLR), Location Item LI_4 (dist=50m, ref=BG_A), Balise group BG_B (new SOLR), Travelled distance since BG_A = 30m.",
      "assumptions": "The OBU uses the travelled distance as the distance between the former SOLR (BG_A) and the new SOLR (BG_B) when linking information is not available.",
      "steps": [
        {
          "no": 1,
          "action": "Detect balise group BG_B and update SOLR to BG_B.",
          "expected": "The OBU identifies BG_B as the new SOLR."
        },
