          "no": 2,
          "action": "Determine the distance between BG_A and BG_B using travelled distance.",
          "expected": "The distance is determined to be 30m."
        },
        {
          "no": 3,
          "action": "Calculate the new distance of LI_4 relative to BG_B.",
          "expected": "The distance is recalculated as 50m - 30m = 20m."
        },
        {
          "no": 4,
          "action": "Verify the internal state of the location item LI_4.",
          "expected": "The location item LI_4 is stored with a distance of 20m and reference balise group BG_B."
        }
      ]
