{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "SMS code generation does not reset failed authentication count",
      "covers": [
        "KDH-024"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a failed authentication count greater than 0 (e.g., 2 failed attempts).",
      "test_inputs": "Valid company representative credentials, valid phone number associated with the account.",
      "assumptions": "The system allows generating a new SMS code even when there are previous failed attempts, provided the account is not locked.",
      "steps": [
        {
          "no": 1,
          "action": "Log in with the company representative account using an incorrect password twice to establish a failed authentication count of 2.",
          "expected": "The system records 2 failed authentication attempts for the account."
        },
        {
          "no": 2,
          "action": "Initiate the process to generate a new SMS one-time code for the account.",
          "expected": "A new SMS one-time code is sent to the registered phone number."
        },
        {
          "no": 3,
          "action": "Check the current failed authentication count for the account in the system logs or database.",
          "expected": "The failed authentication count remains 2 and has not been reset to 0."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "SMS code generation preserves failed count near lockout threshold",
      "covers": [
        "KDH-024"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with a failed authentication count of 4 (assuming a lockout threshold of 5).",
      "test_inputs": "Valid company representative credentials, valid phone number associated with the account.",
      "assumptions": "The account lockout threshold is 5 failed attempts. The system allows SMS code generation at 4 failed attempts.",
      "steps": [
        {
          "no": 1,
          "action": "Log in with the company representative account using an incorrect password four times to establish a failed authentication count of 4.",
          "expected": "The system records 4 failed authentication attempts for the account."
        },
        {
          "no": 2,
          "action": "Initiate the process to generate a new SMS one-time code for the account.",
          "expected": "A new SMS one-time code is sent to the registered phone number."
        },
        {
          "no": 3,
          "action": "Check the current failed authentication count for the account.",
          "expected": "The failed authentication count remains 4 and has not been reset to 0."
        },
        {
          "no": 4,
          "action": "Attempt to log in with an incorrect password a fifth time.",
          "expected": "The account is locked due to reaching the 5th failed attempt, confirming the count was not reset by the SMS generation."
        }
      ]
    }
  ]
}

