{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Multiple authenticator failure threshold triggers disablement",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with password and second-factor authentication enabled. The account is not currently disabled. The failure threshold is defined in VBP SDD §14 (assumed to be 3 for this test).",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold defined in VBP SDD §14 is 3 consecutive failed attempts.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails. The system records a failed attempt for both authenticators."
        },
        {
          "no": 2,
          "action": "Attempt login again with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails. The system records a second failed attempt for both authenticators."
        },
        {
          "no": 3,
          "action": "Attempt login a third time with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails. The system disables both the password authenticator and the second-factor authenticator for the account."
        },
        {
          "no": 4,
          "action": "Attempt login with valid username, correct password, and correct second-factor code.",
          "expected": "Authentication is rejected because the authenticators are disabled."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Single authenticator failure does not disable other authenticators",
      "covers": [
        "KDH-038"
      ],
      "type": "Normal",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor authentication enabled. The account is not currently disabled. The failure threshold is defined in VBP SDD §14 (assumed to be 3 for this test).",
      "test_inputs": "Valid username, invalid password, valid second-factor code.",
      "assumptions": "The failure threshold defined in VBP SDD §14 is 3 consecutive failed attempts. The requirement specifies that *more than one* authenticator must be involved in the consecutive failures to trigger the disablement of *all* involved authenticators. If only one authenticator fails, the specific multi-authenticator disablement logic should not trigger in the same way, or at least the other authenticator should remain active if the failure is isolated to one factor in a way that doesn't meet the 'consecutive failed authentication attempts... involving more than one authenticator' condition. However, typically 'failed authentication' implies the whole process. Let's interpret 'involved' as the factors that were checked and failed. If I fail password but pass 2FA, is 2FA 'involved'? Yes, it was checked. But did it fail? No. The requirement says 'consecutive failed authentication attempts... involving more than one authenticator'. This usually means the attempt failed, and multiple factors were part of the attempt. If the password fails, the 2FA might not even be requested. Let's assume a step-by-step flow: Password first, then 2FA. If password fails, 2FA is not checked. So only one authenticator is 'involved' in the failure. If I provide wrong password and wrong 2FA, both are involved. \n\nLet's refine the test to ensure we test the boundary where only one authenticator is effectively 'involved' in the failure (e.g., password fails, 2FA not reached or not failed).",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username and invalid password.",
          "expected": "Authentication fails at the password stage. The second-factor authenticator is not challenged or is not considered 'failed' in this attempt."
        },
        {
          "no": 2,
          "action": "Attempt login again with valid username and invalid password.",
          "expected": "Authentication fails at the password stage."
        },
        {
          "no": 3,
          "action": "Attempt login a third time with valid username and invalid password.",
          "expected": "Authentication fails. Since only the password authenticator was involved in the failure (2FA was not reached or not failed), the system should NOT disable the second-factor authenticator. The password authenticator may be locked or the account locked per other policies, but the specific KDH-038 behavior of disabling *all involved* authenticators (implying multiple) is not triggered in the same manner, or specifically, the 2FA remains enabled."
        },
        {
          "no": 4,
          "action": "Check the status of the second-factor authenticator for the account.",
          "expected": "The second-factor authenticator is still enabled/active."
        }
      ]
    },
    {
      "id": "TC-003",
      "title": "Failure threshold boundary: one attempt below threshold",
      "covers": [
        "KDH-038"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "A company representative account exists with password and second-factor authentication enabled. The account is not currently disabled. The failure threshold is defined in VBP SDD §14 (assumed to be 3 for this test).",
      "test_inputs": "Valid username, invalid password, invalid second-factor code.",
      "assumptions": "The failure threshold defined in VBP SDD §14 is 3 consecutive failed attempts.",
      "steps": [
        {
          "no": 1,
          "action": "Attempt login with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails. The system records a failed attempt."
        },
        {
          "no": 2,
          "action": "Attempt login again with valid username, invalid password, and invalid second-factor code.",
          "expected": "Authentication fails. The system records a second failed attempt."
        },
        {
          "no": 3,
          "action": "Check the status of the password and second-factor authenticators.",
          "expected": "Both authenticators remain enabled. The threshold (3) has not been reached."
        }
      ]
    }
  ]
}

